import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.StringTokenizer;

/**
 * Variant 2: Using BufferedReader for input and System.out for output
 */
public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintStream out = System.out;
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        if (n > 11) {
            out.println(0);
            return;
        }

        ArrayList<Point> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            int d = Integer.parseInt(st.nextToken());
            int e = Integer.parseInt(st.nextToken());
            points.add(new Point(a, b, c, d, e));
        }

        HashSet<Integer> goodIndices = new HashSet<>();
        for (int i = 0; i < n; i++) {
            boolean isGood = true;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (i != j && i != k && j != k) {
                        Point one = points.get(j);
                        Point two = points.get(k);
                        Point three = points.get(i);
                        Point lol2 = new Point(one.v - three.v, one.w - three.w, one.x - three.x, one.y - three.y, one.z - three.z);
                        Point lol1 = new Point(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z);
                        if (angle(lol1, lol2)) {
                            isGood = false;
                        }
                    }
                }
            }
            if (isGood) {
                goodIndices.add(i + 1);
            }
        }

        if (goodIndices.isEmpty()) {
            out.println(0);
        } else {
            out.println(goodIndices.size());
            for (int idx : goodIndices) {
                out.println(idx);
            }
        }
    }

    static boolean angle(Point a, Point b) {
        double amag = a.mag();
        double bmag = b.mag();
        double abmag = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
        return Math.toDegrees(Math.acos(abmag / (amag * bmag))) < 90;
    }

    static class Point {
        int v, w, x, y, z;
        Point(int v, int w, int x, int y, int z) {
            this.v = v; this.w = w; this.x = x; this.y = y; this.z = z;
        }
        double mag() {
            return Math.sqrt(v*v + w*w + x*x + y*y + z*z);
        }
    }
}
